commit 53a9342cdb6e72fc8238a254c2f500ac3584c572
Author: rakxdev <rakesh.943803@gmail.com>
Date:   Tue Aug 11 07:27:58 2026 +0000

    fix(ui): animations run on ALL devices + compact mobile header + CI hardening

    Root cause (verified in live browser): desktop OS 'reduce motion' was
    switching off the split-flap (static board) and crushing the marquee to a
    0.01ms turbo-flicker via a global CSS override. Mobile looked clean only
    because the phone had the setting off.

    - SplitFlap: drop the prefers-reduced-motion gate — flips always animate
      (armed delay still prevents the initial half-flash)
    - index.css: remove the universal 'animation-duration: .01ms !important'
      kill-all — marquee runs at its designed 110s everywhere
    - App.tsx: MotionConfig reducedMotion 'user' -> 'never' (tilt/magnetic/
      terminal animate on desktop too)
    - PublicShell: USAGE + CREDITS hidden on phones (<sm) — header is one
      compact 56px row again (was 71px wrapped); footer still links both
    - LATENT BREAKS from the Dependabot majors, caught by the dashboard
      typecheck: TS7 removed tsconfig baseUrl (removed); lucide-react 1.x
      removed the Github brand icon (swapped to ExternalLink)
    - ci.yml hardened: dashboard typecheck + build and packages build+tests
      are now part of the quality gate (they were missing — which is why the
      TS7/lucide breaks slipped through green)

    Verified live: flips animating (14 elements), marquee 110s, no
    reduced-motion rules in the prod CSS, mobile header single-row at 390px.

diff --git a/.github/workflows/ci.yml b/.github/workflows/ci.yml
index 81e082e..a1b2b2f 100644
--- a/.github/workflows/ci.yml
+++ b/.github/workflows/ci.yml
@@ -32,6 +32,12 @@ jobs:

       - name: Unit tests
         run: npm test
+      - name: Dashboard typecheck
+        run: cd dashboard && npx tsc --noEmit
+      - name: Dashboard build
+        run: cd dashboard && npm run build
+      - name: Packages build + tests (SDK + MCP wrapper)
+        run: npm run build:packages && npm run test:packages

       - name: Build gate (worker bundles)
         run: cd gateway && npx wrangler deploy --dry-run | grep -q "Total Upload"
diff --git a/dashboard/src/App.tsx b/dashboard/src/App.tsx
index a899fb9..d5728c7 100644
--- a/dashboard/src/App.tsx
+++ b/dashboard/src/App.tsx
@@ -49,7 +49,7 @@ export default function AppShell() {
     }`;

   return (
-    <MotionConfig reducedMotion="user">
+    <MotionConfig reducedMotion="never">
       <div className="min-h-screen flex flex-col">
         <header className="sticky top-0 z-40 flex items-center gap-3 px-4 sm:px-5 py-3 border-b border-line bg-bg/85 backdrop-blur">
           <Link to="/apps" className="flex items-center gap-3">
diff --git a/dashboard/src/components/PublicShell.tsx b/dashboard/src/components/PublicShell.tsx
index 48c4e19..380038d 100644
--- a/dashboard/src/components/PublicShell.tsx
+++ b/dashboard/src/components/PublicShell.tsx
@@ -26,7 +26,7 @@ export function PublicHeader({ tag }: { tag: string }) {
         <Link
           to="/usage"
           aria-current={tag === "USAGE" ? "true" : undefined}
-          className={`font-mono text-[10px] sm:text-[10.5px] tracking-[0.16em] px-2.5 py-1.5 rounded-md transition-colors ${
+          className={`hidden sm:inline-flex font-mono text-[10px] sm:text-[10.5px] tracking-[0.16em] px-2.5 py-1.5 rounded-md transition-colors ${
             tag === "USAGE" ? "text-gold bg-panel2" : "text-inkdim hover:text-ink"
           }`}
         >
@@ -35,7 +35,7 @@ export function PublicHeader({ tag }: { tag: string }) {
         <Link
           to="/credits"
           aria-current={tag === "CREDITS" ? "true" : undefined}
-          className={`font-mono text-[10px] sm:text-[10.5px] tracking-[0.16em] px-2.5 py-1.5 rounded-md transition-colors ${
+          className={`hidden sm:inline-flex font-mono text-[10px] sm:text-[10.5px] tracking-[0.16em] px-2.5 py-1.5 rounded-md transition-colors ${
             tag === "CREDITS" ? "text-gold bg-panel2" : "text-inkdim hover:text-gold"
           }`}
         >
diff --git a/dashboard/src/components/SplitFlap.tsx b/dashboard/src/components/SplitFlap.tsx
index 9ca60b4..e9110d5 100644
--- a/dashboard/src/components/SplitFlap.tsx
+++ b/dashboard/src/components/SplitFlap.tsx
@@ -148,8 +148,10 @@ export default function SplitFlap({
   const [armed, setArmed] = useState(false);

   useEffect(() => {
-    const reduced = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
-    if (reduced) setAnimate(false);
+    // flips ALWAYS animate — the OS "reduce motion" setting is intentionally
+    // ignored (founder call): desktop was rendered static while mobile was
+    // clean. The `armed` delay still prevents an initial half-flash.
+    setAnimate(true);
     const t = window.setTimeout(() => setArmed(true), delay);
     return () => clearTimeout(t);
   }, [delay]);
diff --git a/dashboard/src/index.css b/dashboard/src/index.css
index 0ce39f4..4d2b4fa 100644
--- a/dashboard/src/index.css
+++ b/dashboard/src/index.css
@@ -59,15 +59,9 @@ body {
   background: rgba(217, 182, 74, 0.35);
 }

-/* OS-level reduced motion fallback (belt to MotionConfig's suspenders) */
-@media (prefers-reduced-motion: reduce) {
-  *,
-  *::before,
-  *::after {
-    animation-duration: 0.01ms !important;
-    transition-duration: 0.01ms !important;
-  }
-}
+/* NOTE: no OS-level reduced-motion kill-all here — the 0.01ms override made
+   infinite animations (marquee) flicker at turbo speed on desktops with the
+   OS setting on. All animations run at their designed speeds everywhere. */

 /* safe areas for notched phones */
 @supports (padding: env(safe-area-inset-bottom)) {
