function sseParse(text: string): unknown {
  const dataLines = text.split("\n\n").flatMap((b) => b.split("\n").filter((l) => l.startsWith("data:")).map((l) => l.slice(5).trim()));
  if (dataLines.length === 0) return null;
  try { return JSON.parse(dataLines.join("")); } catch { return { raw: text.slice(0, 200) }; }
}
